package dev.pocketengine;
import dev.pocketengine.core.RunControl;
import java.lang.reflect.Field;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ConcurrentHashMap;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.Shadows;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=EngineApplication.class)
public final class NativeModelStreamPresentationTest {
 static final class Fixture {
  final EngineApplication app=(EngineApplication)RuntimeEnvironment.getApplication();final JSONObject task;final RunControl control=new RunControl();final List<JSONObject> events=new CopyOnWriteArrayList<>();final String request=UUID.randomUUID().toString();
  @SuppressWarnings("unchecked") Fixture()throws Exception{task=app.tasks.startAttempt(app.tasks.createCapabilityTask("real transient preview","conversation").getString("id"),"capabilities",8);control.bindHostRun(task.getString("id"),task.getString("runId"),task.getInt("coordinatorEpoch"));Field f=EngineApplication.class.getDeclaredField("capabilityControls");f.setAccessible(true);((ConcurrentHashMap<String,RunControl>)f.get(app)).put(task.getString("id"),control);app.addObserver(e->{if(e.optString("type").equals("model_stream"))try{events.add(new JSONObject(e.toString()));}catch(Exception impossible){throw new IllegalStateException(impossible);}});}
  JSONObject event(String kind,String request,long sequence,long pause,String text)throws Exception{JSONObject body=new JSONObject().put("kind",kind).put("requestId",request).put("sequence",sequence).put("provider","openai_chat").put("pauseRevision",pause).put("provisional",kind.equals("text_delta")).put("taskCompleted",false);if(kind.equals("text_delta"))body.put("text",text);if(kind.matches("cancelled|failed"))body.put("discardDraft",true).put("code","fixture_cancel");return new JSONObject().put("type","model_stream").put("status","running").put("stream",body);}
  void emit(String kind,String request,long sequence,long pause,String text)throws Exception{app.recordRunEvent(task.getString("id"),task.getString("runId"),task.getInt("coordinatorEpoch"),control,event(kind,request,sequence,pause,text));}
  void idle(){Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}
 }
 @Test public void actualAppStreamEventsNeverWriteTaskEventsStatusOrFormalMessages()throws Exception{Fixture f=new Fixture();String before=f.app.tasks.get(f.task.getString("id"),false).toString();f.emit("started",f.request,1,0,"");f.emit("text_delta",f.request,2,0,"temporary visible words");f.emit("completed",f.request,3,0,"");f.idle();assertEquals(3,f.events.size());assertEquals(before,f.app.tasks.get(f.task.getString("id"),false).toString());for(JSONObject e:f.events){assertFalse(e.has("status"));assertFalse(e.getJSONObject("stream").getBoolean("taskCompleted"));}f.control.cancel();f.idle();assertTrue(f.events.get(f.events.size()-1).getJSONObject("stream").getBoolean("discardDraft"));assertEquals(before,f.app.tasks.get(f.task.getString("id"),false).toString());}
 @Test public void cancellationBeforeMainHandoffDeliversOnlyExactDraftDiscardNeverLateText()throws Exception{Fixture f=new Fixture();f.emit("started",f.request,1,0,"");f.emit("text_delta",f.request,2,0,"old visible draft");f.control.cancel();f.idle();assertFalse(f.events.toString().contains("old visible draft"));assertTrue(f.events.stream().allMatch(e->e.optJSONObject("stream").optBoolean("discardDraft")));}
 @Test public void pauseAbaAndLateOldCleanupCannotEraseTheNewRequestsDraft()throws Exception{Fixture f=new Fixture();f.emit("started",f.request,1,0,"");f.emit("text_delta",f.request,2,0,"old paused draft");f.control.pause();f.control.resume();String newer=UUID.randomUUID().toString();long pause=f.control.pauseRevision();f.emit("started",newer,1,pause,"");f.emit("text_delta",newer,2,pause,"current new draft");f.emit("cancelled",f.request,9,0,"");f.idle();assertFalse(f.events.toString().contains("old paused draft"));assertTrue(f.events.toString().contains("current new draft"));JSONObject last=f.events.get(f.events.size()-1);assertEquals(newer,last.getJSONObject("stream").getString("requestId"));assertEquals("text_delta",last.getJSONObject("stream").getString("kind"));}
 @Test public void aReplacementControlOrStaleRunCannotCreateADraft()throws Exception{Fixture f=new Fixture();RunControl foreign=new RunControl();foreign.bindHostRun(f.task.getString("id"),f.task.getString("runId"),f.task.getInt("coordinatorEpoch"));f.app.recordRunEvent(f.task.getString("id"),f.task.getString("runId"),f.task.getInt("coordinatorEpoch"),foreign,f.event("started",f.request,1,0,""));f.app.recordRunEvent(f.task.getString("id"),UUID.randomUUID().toString(),f.task.getInt("coordinatorEpoch"),f.control,f.event("started",f.request,1,0,""));f.idle();assertEquals(0,f.events.size());}
 @Test public void ordinaryRunnerFailureClearsEvenACompletedPresentationBeforeCanonicalTaskEvent()throws Exception{Fixture f=new Fixture();f.emit("started",f.request,1,0,"");f.emit("text_delta",f.request,2,0,"not a committed reply");f.emit("completed",f.request,3,0,"");f.idle();f.app.recordRunEvent(f.task.getString("id"),f.task.getString("runId"),f.task.getInt("coordinatorEpoch"),f.control,new JSONObject().put("type","result").put("status","failed").put("message","canonical failed"));f.idle();assertTrue(f.events.get(f.events.size()-1).getJSONObject("stream").getBoolean("discardDraft"));JSONObject task=f.app.tasks.get(f.task.getString("id"),false);assertEquals("failed",task.getString("status"));assertFalse(task.toString().contains("not a committed reply"));assertEquals(1,task.getJSONArray("events").length());}
 @Test public void actualAppInjectsTheSameLocalOcrIntoTheAttachmentReaderWithoutRunningJni()throws Exception{Fixture f=new Fixture();assertNotNull(f.app.localOcr);assertEquals("dev.pocketengine.vision.ocr.TesseractLocalOcrEngine",f.app.localOcr.getClass().getName());Object attachments=f.app.features.module("attachments");Field documents=attachments.getClass().getDeclaredField("documents");documents.setAccessible(true);Object reader=documents.get(attachments);Field rf=reader.getClass().getDeclaredField("reader");rf.setAccessible(true);Object documentReader=rf.get(reader);Field ocr=documentReader.getClass().getDeclaredField("ocr");ocr.setAccessible(true);assertSame(f.app.localOcr,ocr.get(documentReader));assertTrue(f.app.localOcr.engineVersion().contains("eng+chi_sim"));}
 @Test public void realSseModelLoopReachesActualControllerDraftThenOnlyCanonicalReplyIsPersisted()throws Exception{
  EngineApplication app=(EngineApplication)RuntimeEnvironment.getApplication();dev.pocketengine.ui.PocketWorldController controller=new dev.pocketengine.ui.PocketWorldController(new dev.pocketengine.ui.ComposeActivity(),app);controller.attach();List<JSONObject> transientEvents=new CopyOnWriteArrayList<>();app.addObserver(e->{if(e.optString("type").equals("model_stream"))transientEvents.add(e);});java.util.concurrent.CountDownLatch sent=new java.util.concurrent.CountDownLatch(1),finish=new java.util.concurrent.CountDownLatch(1);dev.pocketengine.testutil.HttpServer server=dev.pocketengine.testutil.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);server.createContext("/v1/chat/completions",exchange->{try{
   exchange.getRequestBody().readAllBytes();exchange.getResponseHeaders().add("Content-Type","text/event-stream");exchange.sendResponseHeaders(200,0);String first="data: {\"id\":\"reply\",\"object\":\"chat.completion.chunk\",\"choices\":[{\"index\":0,\"delta\":{\"role\":\"assistant\",\"content\":\"actual \"},\"finish_reason\":null}]}\n\n";exchange.getResponseBody().write(first.getBytes(java.nio.charset.StandardCharsets.UTF_8));exchange.getResponseBody().flush();sent.countDown();finish.await(10,java.util.concurrent.TimeUnit.SECONDS);String tail="data: {\"id\":\"reply\",\"object\":\"chat.completion.chunk\",\"choices\":[{\"index\":0,\"delta\":{\"content\":\"streamed reply\"},\"finish_reason\":null}]}\n\ndata: {\"id\":\"reply\",\"object\":\"chat.completion.chunk\",\"choices\":[{\"index\":0,\"delta\":{},\"finish_reason\":\"stop\"}]}\n\ndata: [DONE]\n\n";exchange.getResponseBody().write(tail.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception failure){throw new IllegalStateException(failure);}finally{exchange.close();}});server.start();var worker=java.util.concurrent.Executors.newSingleThreadExecutor();
  try{
   app.settings.save(new JSONObject().put("baseUrl","http://127.0.0.1:"+server.getAddress().getPort()+"/v1").put("clearApiKey",true).put("model","fixture-model").put("provider","openai_chat").put("sendScreenshots",false).put("maxSteps",5).put("requestTimeoutSeconds",10).put("maxOutputTokens",4096));
   var assistant=app.features.module("assistant");JSONObject ack=assistant.handle("send",new JSONObject().put("message","real SSE reply").put("clientMessageId",UUID.randomUUID().toString()).put("executionScope",new JSONObject().put("deadlineAt",0L).put("toolLimit",5).put("modelCallLimit",13)));
   assertEquals(ack.toString(),"accepted",ack.getString("status"));String id=ack.getString("taskId");
   assertTrue("first HTTP missing; task="+app.tasks.get(id,false)+" uiError="+controller.getState().getError(),sent.await(5,java.util.concurrent.TimeUnit.SECONDS));
   long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(5);while(System.nanoTime()<deadline&&!controller.getState().getModelDrafts().values().stream().anyMatch(d->d.getText().contains("actual "))){Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();Thread.sleep(10);}
   assertTrue("drafts="+controller.getState().getModelDrafts()+" events="+transientEvents+" task="+app.tasks.get(id,false),controller.getState().getModelDrafts().values().stream().anyMatch(d->d.getText().contains("actual ")));assertFalse(app.tasks.get(id,false).getJSONArray("events").toString().contains("model_stream"));finish.countDown();
   deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(10);while(System.nanoTime()<deadline&&assistant.snapshot().optBoolean("running")){Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();Thread.sleep(10);}
   assertFalse("original turn did not finish: "+app.tasks.get(id,false),assistant.snapshot().optBoolean("running"));Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();
   JSONObject conversation=assistant.handle("get",new JSONObject().put("conversationId",ack.getString("conversationId")));org.json.JSONArray messages=conversation.getJSONArray("messages");int replies=0;for(int i=0;i<messages.length();i++)if("assistant".equals(messages.getJSONObject(i).optString("role"))){replies++;assertEquals("actual streamed reply",messages.getJSONObject(i).getString("content"));}assertEquals(1,replies);
   assertTrue("terminal drafts="+controller.getState().getModelDrafts(),controller.getState().getModelDrafts().isEmpty());assertFalse(app.tasks.get(id,false).getJSONArray("events").toString().contains("model_stream"));assertEquals(1,app.tasks.get(id,false).getJSONObject("executionScope").getInt("modelCallsUsed"));
  }finally{finish.countDown();worker.shutdownNow();server.stop(0);controller.detach();}
 }

 @Test public void failedAttemptQueuedBeforeReplacementPreservesOneVisibleBoundary()throws Exception{Fixture f=new Fixture();String next=UUID.randomUUID().toString();f.emit("started",f.request,1,0,"");f.emit("text_delta",f.request,2,0,"visible interrupted prefix");f.emit("failed",f.request,3,0,"");f.emit("started",next,1,0,"");f.emit("text_delta",next,2,0,"fresh response");f.idle();assertEquals(5,f.events.size());assertEquals("visible interrupted prefix",f.events.get(1).getJSONObject("stream").getString("text"));assertFalse(f.events.get(2).getJSONObject("stream").optBoolean("discardDraft"));assertEquals(next,f.events.get(3).getJSONObject("stream").getString("requestId"));assertFalse(f.app.tasks.get(f.task.getString("id"),false).toString().contains("visible interrupted prefix"));}

}
